mapper.select:
SELECT id FROM sq_sandbox_execution WHERE user_id=#{userId} AND scope_id=#{scopeId}
AND status IN ('IN_FLIGHT',
'UNKNOWN') AND del_flag='0' FOR UPDATE

SELECT model_selection_json
FROM sq_response_execution
WHERE user_id = #{userId}
AND binding_id = #{bindingId}

SELECT r.model_selection_json
FROM sq_response_execution r
JOIN sq_runtime_binding b ON b.user_id = r.user_id AND b.binding_id = r.binding_id
WHERE r.user_id = #{userId}
AND b.framework_session_id = #{sessionId}
